events.command:
/bin/bash -lc "awk '
/<Iteration_query-def>/ {q="'$0; sub(/''^.*<Iteration_query-def>/,"",q); sub(/<'"\\\\/Iteration_query-def>.*"'$/, "",q);}
/<Hit_num>1<'"\\\\/Hit_num>/ {in1=1; gotdef=0; gotid=0; gotlen=0; def=\"\"}
in1 && /<Hit_def>/ && "'!gotdef {def=$0; sub(/''^.*<Hit_def>/,"",def); sub(/<'"\\\\/Hit_def>.*"'$/, "",def); gotdef=1}
in1 && /<Hsp_identity>/ && !gotid {id=$0; sub(/''^.*<Hsp_identity>/,"",id); sub(/<'"\\\\/Hsp_identity>.*"'$/, "",id); gotid=1}
in1 && /<Hsp_align-len>/ && !gotlen {al=$0; sub(/''^.*<Hsp_align-len>/,"",al); sub(/<'"\\\\/Hsp_align-len>.*"'$/, "",al); gotlen=1}
/<'"\\\\/Iteration>/ {if(q"'!="") print q "'"\\t\" id \"/\" al \"\\t\" def; q=\"\"; in1=0}
' work/blast1000.xml > work/top_hits.tsv
wc -l work/top_hits.tsv; sed -n '1,20p' work/top_hits.tsv; printf '\\nIdentity distribution:\\n'; awk -F '\\t' '{split("'$2,a,"/"); print a[1] "/" a[2]}'"' work/top_hits.tsv | sort | uniq -c | sort -nr | head -30; printf '\\nTop first-hit genus-ish prefixes:\\n'; cut -f3 work/top_hits.tsv | sed -E 's/"'^PREDICTED: //; s/''^([A-Z][a-z]+) .*/'"\\1/; s/"'^([A-Z][a-z]+) .*/'"\\1/' | sort | uniq -c | sort -nr | head -30"

/bin/bash -lc "awk '
function getval(s,tag,   x,y) {x=index(s,\"<\" tag \">\"); if("'!x) return ""; s=substr(s,x+length(tag)+2); y=index(s,"</" tag ">"); if(!y) return ""; return substr(s,1,y-1)}
/<Iteration_query-def>/ {q=getval($0,"Iteration_query-def")}
/<Hit_num>1<'"\\/Hit_num>/ {in1=1; gotdef=0; gotid=0; gotlen=0; def=\"\"}
in1 && /<Hit_def>/ && "'!gotdef {def=getval($0,"Hit_def"); gotdef=1}
in1 && /<Hsp_identity>/ && !gotid {id=getval($0,"Hsp_identity"); gotid=1}
in1 && /<Hsp_align-len>/ && !gotlen {al=getval($0,"Hsp_align-len"); gotlen=1}
{if(index($0,"</Iteration>") && q!="") {print q "'"\\t\" id \"/\" al \"\\t\" def; q=\"\"; in1=0}}
' work/blast1000.xml > work/top_hits.tsv
wc -l work/top_hits.tsv; sed -n '1,20p' work/top_hits.tsv; printf '\\nIdentity distribution:\\n'; awk -F '\\t' '{print "'$2}'"' work/top_hits.tsv | sort | uniq -c | sort -nr | head -30; printf '\\nTop first-hit organism prefixes:\\n'; cut -f3 work/top_hits.tsv | sed -E 's/"'^PREDICTED: //; s/''^([A-Z][a-z]+) .*/'"\\1/' | sort | uniq -c | sort -nr | head -30"

/bin/bash -lc "awk '
function getval(s,tag,   x,y) {x=index(s,\"<\" tag \">\"); if("'!x) return ""; s=substr(s,x+length(tag)+2); y=index(s,"</" tag ">"); if(!y) return ""; return substr(s,1,y-1)}
/<Iteration_query-def>/ {q=getval($0,"Iteration_query-def")}
/<Hit_num>1<'"\\/Hit_num>/ {in1=1; gotdef=0; gotid=0; gotlen=0; def=\"\"}
